class Lfm3OmniEncoderCausalConv2D(nn.Conv2d):
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: int,
        cache_key: str,
        stride: int = 1,
        padding: int = 0,
        dilation: int = 1,
        groups: int = 1,
    ):
        super().__init__(
            in_channels, out_channels, kernel_size, stride=stride, padding=padding, dilation=dilation, groups=groups
        )
        self.cache_key = cache_key

    @property
    def left_pad(self):
        return self.kernel_size[0] - self.stride[0]

    @property
    def left_pad_init(self):
        return self.left_pad

    @property
    def time_pad(self):
        return (self.left_pad, 0)

    @property
    def freq_pad(self):
        return ((self.kernel_size[1] - 1) // 2, (self.kernel_size[1] - 1) // 2)

    def output_length(self, input_lengths: torch.Tensor | None, streaming: bool = False) -> torch.Tensor | None:
        if input_lengths is None:
            return None

        return -(input_lengths // -self.stride[0])

    def forward(
        self, x: torch.Tensor, padding_cache: Lfm3OmniEncoderCausalConvPaddingCache | None = None
    ) -> torch.Tensor:
        # last chunk of a stream: right-pad to a multiple of the stride, as offline
        x = nn.functional.pad(x, (0, 0, 0, -x.shape[2] % self.stride[0]))
        x = nn.functional.pad(x, (self.freq_pad[0], self.freq_pad[1]))
        if padding_cache is not None:
            x = padding_cache.update(x, self.cache_key, self)
        else:
            x = nn.functional.pad(x, (0, 0, self.time_pad[0], self.time_pad[1]))

        return super().forward(x)


def _mask_subsampled_frames(hidden_states: torch.Tensor, lengths: torch.Tensor | None) -> torch.Tensor:
    """Zero out time frames beyond each sequence's valid length so they don't leak into the next conv."""
    if lengths is None:
        return hidden_states
    time = torch.arange(hidden_states.shape[2], device=hidden_states.device)
    return hidden_states * (time < lengths[:, None])[:, None, :, None]


class Lfm3OmniEncoderSubsamplingLayer(nn.Module):
    """Depthwise-separable subsampling stage: depthwise strided causal Conv2d + 1x1 pointwise Conv2d."""

    def __init__(self, config: Lfm3OmniAudioConfig, layer_idx: int):
        super().__init__()
        channels = config.subsampling_conv_channels
        self.depthwise_conv = Lfm3OmniEncoderCausalConv2D(
            channels,
            channels,
            kernel_size=config.subsampling_conv_kernel_size,
            stride=config.subsampling_conv_stride,
            groups=channels,
            cache_key=f"subsampling.{layer_idx}",
        )
        self.pointwise_conv = nn.Conv2d(channels, channels, kernel_size=1)

    def forward(
        self,
        hidden_states: torch.Tensor,
        lengths: torch.Tensor | None,
        padding_cache: Lfm3OmniEncoderCausalConvPaddingCache | None = None,
    ) -> tuple[torch.Tensor, torch.Tensor | None]:
        hidden_states = self.depthwise_conv(hidden_states, padding_cache=padding_cache)
        lengths = self.depthwise_conv.output_length(lengths, streaming=padding_cache is not None)
        hidden_states = self.pointwise_conv(hidden_states)
        return _mask_subsampled_frames(hidden_states, lengths), lengths


class Lfm3OmniEncoderSubsamplingConv2D(nn.Module):
    def __init__(self, config: Lfm3OmniAudioConfig):
        super().__init__()
        channels = config.subsampling_conv_channels
        num_layers = int(math.log2(config.subsampling_factor))

        # stem: strided causal conv over the single-channel mel spectrogram
        self.conv_in = Lfm3OmniEncoderCausalConv2D(
            1,
            channels,
            kernel_size=config.subsampling_conv_kernel_size,
            stride=config.subsampling_conv_stride,
            cache_key="subsampling.0",
        )
        # depthwise-separable layers
        self.layers = nn.ModuleList(Lfm3OmniEncoderSubsamplingLayer(config, layer_idx=i) for i in range(1, num_layers))
        self.act_fn = nn.SiLU()
        # a pointwise convolution in place of Nemotron's linear
        self.conv_out = nn.Conv1d(config.subsampling_out_hidden_size, config.hidden_size, kernel_size=1)

    def forward(
        self,
        input_features: torch.Tensor,
        attention_mask: torch.Tensor = None,
        padding_cache: Lfm3OmniEncoderCausalConvPaddingCache | None = None,
    ):
        hidden_states = input_features.unsqueeze(1)
        lengths = attention_mask.sum(-1) if attention_mask is not None else None

        # stem stage
        hidden_states = self.conv_in(hidden_states, padding_cache=padding_cache)
        lengths = self.conv_in.output_length(lengths, streaming=padding_cache is not None)
        hidden_states = self.act_fn(_mask_subsampled_frames(hidden_states, lengths))

        # depthwise-separable stages
        for layer in self.layers:
            hidden_states, lengths = layer(hidden_states, lengths, padding_cache=padding_cache)
            hidden_states = self.act_fn(hidden_states)

        hidden_states = hidden_states.transpose(1, 2).flatten(2)
        hidden_states = self.conv_out(hidden_states.transpose(1, 2)).transpose(1, 2)

        return hidden_states


@auto_docstring(
    custom_intro="""
    The LFM3-Audio speech encoder.
    """
)
class Lfm3OmniAudioModel(Lfm3OmniPreTrainedModel):
    """LFM2 model with a sliding-attention layer type; the mask and rotary embedding are built per layer type."""

    config: Lfm3OmniAudioConfig
    main_input_name = "input_features"
    input_modalities = "audio"
    _can_record_outputs = {
        "hidden_states": Lfm3OmniEncoderLayer,
        "attentions": Lfm3OmniEncoderAttention,
    }

    def __init__(self, config: Lfm3OmniAudioConfig):
        super().__init__(config)
        self.layers = nn.ModuleList(
            [Lfm3OmniEncoderLayer(config, layer_idx) for layer_idx in range(config.num_hidden_layers)]
        )
        self.rotary_emb = Lfm3OmniRotaryEmbedding(config=config)
        self.gradient_checkpointing = False
        self.embedding_norm = Lfm3OmniRMSNorm(config.hidden_size, eps=config.norm_eps)
        self.subsampling = Lfm3OmniEncoderSubsamplingConv2D(config)

        # Initialize weights and apply final processing
        self.post_init()

    @merge_with_config_defaults
    @capture_outputs
    @auto_docstring
    @deprecate_kwarg("past_key_values", "5.40.0", new_name="cache")
    def forward(
        self,
        input_features: torch.FloatTensor,
        input_features_mask: torch.Tensor | None = None,
        position_ids: torch.LongTensor | None = None,
        cache: Cache | None = None,
        padding_cache: Lfm3OmniEncoderCausalConvPaddingCache | None = None,
        use_cache: bool | None = None,
        **kwargs: Unpack[TransformersKwargs],
    ) -> Lfm3OmniAudioModelOutput:
        r"""
        input_features (`torch.FloatTensor` of shape `(batch_size, num_frames, num_mel_bins)`):
            Log-mel spectrograms, right-padded. When streaming: one chunk of a multiple of
            `config.subsampling_factor` frames, except the last.
        input_features_mask (`torch.Tensor` of shape `(batch_size, num_frames)`, *optional*):
            Mask of the valid spectrogram frames.
        padding_cache (`Lfm3OmniEncoderCausalConvPaddingCache`, *optional*):
            Subsampling streaming state: an empty one with the first chunk, then the returned one.
        """
        if use_cache:
            if cache is None:
                cache = DynamicCache(config=self.config)

            if padding_cache is None:
                padding_cache = Lfm3OmniEncoderCausalConvPaddingCache()

        inputs_embeds = self.subsampling(input_features, input_features_mask, padding_cache=padding_cache)

        past_seen_tokens = cache.get_seq_length() if cache is not None else 0
        if position_ids is None:
            position_ids = torch.arange(inputs_embeds.shape[1], device=inputs_embeds.device) + past_seen_tokens
            position_ids = position_ids.unsqueeze(0)

        output_mask = attention_mask = None
        if input_features_mask is not None:
            output_mask = input_features_mask[:, :: self.config.subsampling_factor]
            # cached tokens are all valid
            attention_mask = nn.functional.pad(output_mask, (past_seen_tokens, 0), value=1)

        mask_kwargs = {
            "config": self.config,
            "inputs_embeds": inputs_embeds,
            "attention_mask": attention_mask,
            "cache": cache,
            "position_ids": position_ids,
        }
        mask_creation_functions = {
            "full_attention": lambda: create_causal_mask(**mask_kwargs),
            "sliding_attention": lambda: create_sliding_window_causal_mask(**mask_kwargs),
            "conv": lambda: create_recurrent_attention_mask(**mask_kwargs),
        }
        causal_mask_mapping = {}
        for layer_type in set(self.config.layer_types):
            causal_mask_mapping[layer_type] = mask_creation_functions[layer_type]()

        hidden_states = inputs_embeds
        position_embeddings = {
            layer_type: self.rotary_emb(hidden_states, position_ids=position_ids, layer_type=layer_type)
            for layer_type in self.rotary_emb.layer_types
        }

        for i, encoder_layer in enumerate(self.layers[: self.config.num_hidden_layers]):
            layer_type = self.config.layer_types[i]
            hidden_states = encoder_layer(
                hidden_states,
                attention_mask=causal_mask_mapping[layer_type],
                position_embeddings=position_embeddings.get(layer_type),
                position_ids=position_ids,
                cache=cache,
                **kwargs,
            )

        hidden_states = self.embedding_norm(hidden_states)

        return Lfm3OmniAudioModelOutput(
            last_hidden_state=hidden_states,
            attention_mask=output_mask,
            cache=cache,
            padding_cache=padding_cache,
        )


@auto_docstring(
    custom_intro="""
    The LFM3-Audio depth decoder, a bidirectional transformer over the codebooks of a speech frame, conditioned on the
    language model's hidden state preceding the frame.
    """
)
class Lfm3OmniDepthDecoderModel(Lfm3OmniPreTrainedModel):
    """LFM2 model with a sliding-attention layer type; the mask and rotary embedding are built per layer type."""

    config: Lfm3OmniDepthDecoderConfig

    def __init__(self, config: Lfm3OmniDepthDecoderConfig):
        super().__init__(config)
        self.embed_tokens = Lfm3OmniDepthDecoderEmbeddings(config)
        self.layers = nn.ModuleList(
            [Lfm3OmniDecoderLayer(config, layer_idx) for layer_idx in range(config.num_hidden_layers)]
        )
        self.rotary_emb = Lfm3OmniRotaryEmbedding(config=config)
        self.gradient_checkpointing = False
        self.embedding_norm = Lfm3OmniRMSNorm(config.hidden_size, eps=config.norm_eps)
        self.num_codebooks = config.num_codebooks
        self.backbone_projector = nn.Linear(config.backbone_hidden_size, config.num_codebooks * config.hidden_size)

        # Initialize weights and apply final processing
        self.post_init()

    @merge_with_config_defaults
    @capture_outputs
    @auto_docstring
    def forward(
        self,
        input_ids: torch.LongTensor | None = None,
        backbone_last_hidden_state: torch.FloatTensor | None = None,
        inputs_embeds: torch.FloatTensor | None = None,
        **kwargs: Unpack[TransformersKwargs],
    ) -> BaseModelOutput:
        r"""
        input_ids (`torch.LongTensor` of shape `(num_frames, num_codebooks)`, *optional*):
            Codes of each frame; `codebook_size` marks a masked codebook.
        backbone_last_hidden_state (`torch.FloatTensor` of shape `(num_frames, backbone_hidden_size)`):
            The language model's hidden state at the position preceding each frame.
        """
        if (input_ids is None) ^ (inputs_embeds is not None):
            raise ValueError("You must specify exactly one of input_ids or inputs_embeds")

        if inputs_embeds is None:
            inputs_embeds = self.embed_tokens(input_ids)

        backbone_embeds = self.backbone_projector(backbone_last_hidden_state).unflatten(-1, (self.num_codebooks, -1))
        hidden_states = inputs_embeds + backbone_embeds
        position_ids = torch.arange(self.num_codebooks, device=hidden_states.device)[None]

        attention_mask = create_bidirectional_mask(
            config=self.config, inputs_embeds=hidden_states, attention_mask=None
        )
        position_embeddings = {
            layer_type: self.rotary_emb(hidden_states, position_ids=position_ids, layer_type=layer_type)
            for layer_type in self.rotary_emb.layer_types
        }

        for i, decoder_layer in enumerate(self.layers[: self.config.num_hidden_layers]):
            layer_type = self.config.layer_types[i]
            hidden_states = decoder_layer(
                hidden_states,
                attention_mask=attention_mask,
                position_embeddings=position_embeddings.get(layer_type),
                position_ids=position_ids,
                is_causal=False,
                **kwargs,
            )

        hidden_states = self.embedding_norm(hidden_states)

        return BaseModelOutput(last_hidden_state=hidden_states)


